import { io } from "socket.io-client";

const SOCKET_URL = "http://localhost:5001"; // Change if needed

export const socket = io(SOCKET_URL, {
  transports: ["websocket"], // Ensures a stable connection
  autoConnect: false, // Prevents auto-connect; you must explicitly call socket.connect()
});

// Event listener for debugging connection status
socket.on("connect", () => {
  console.log("✅ Socket connected:", socket.id);
});

socket.on("disconnect", (reason) => {
  console.warn("❌ Socket disconnected:", reason);
});

socket.on("connect_error", (error) => {
  console.error("⚠️ Socket connection error:", error);
});
